#!/usr/bin/env bash
set -e
cd "$(git rev-parse --show-toplevel)"
echo '>> Aplicando melhorias na main...'

git checkout main
git pull origin main

rm -f src/Arroz.js src/Feijao.js src/Macarrao.js

python3 - <<'PYAPPLY'
import base64, os
FILES = {
  'App.js': '',
  'README.md': '',
  'src/AcompanharPedido.js': '',
  'src/CardapioCacarola.js': '',
  'src/FinalizarPedido.js': '',
  'src/Home.js': '',
  'src/MeusPedidos.js': '',
  'src/TelaProduto.js': '',
  'src/restaurante/ConfiguracoesRestaurante.js': '',
  'src/restaurante/EditarPrato.js': '',
  'src/restaurante/PainelRestaurante.js': '',
  'src/services/storage.js': '',
}
for path, b64 in FILES.items():
  os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
  with open(path, 'wb') as fh:
    fh.write(base64.b64decode(b64))
  print('  escrito:', path)
PYAPPLY

git add -A
git -c user.name="rafafrassetto" -c user.email="rafafrass@gmail.com" commit -m "feat: melhorias de UX no app cliente e painel do restaurante

- TelaProduto: restaura banner 'Ver carrinho' ao reabrir prato que ja esta no carrinho
- AcompanharPedido: auto-avanco de etapas (4s/4s), previsao de tempo na etapa 'A caminho', seta de voltar e botao final para avaliacao
- MeusPedidos: remove botao 'Editar', troca 'Excluir' por 'Cancelar pedido' com confirmacao e taxa fixa acumulada de R\$ 10 cobrada no proximo pedido
- FinalizarPedido: exibe taxa de cancelamento pendente no resumo e limpa apos pagamento
- Home: substitui secao 'Atalhos' por barra de navegacao fixa no rodape com icone destacado do carrinho
- EditarPrato: mascara BRL no preco por kg, mascaras numericas, campo opcional de URL para imagem personalizada com recomendacao de tamanho, destaque em vermelho de campos invalidos
- PainelRestaurante: icone da engrenagem (Configuracoes) ligeiramente menor
- ConfiguracoesRestaurante: troca aviso de cache offline por 'dados sincronizados com o banco em nuvem'
- Remove wrappers Arroz/Feijao/Macarrao e unifica navegacao via TelaProduto com titulo dinamico
- storage: novo namespace CancelFee para taxa de cancelamento acumulada
- README: adiciona secao 'Estrutura do projeto' com arvore de pastas e fluxo resumido"
git push origin main
echo '>> Tudo certo.'
